@staticmethod
def climate_set_mode(data: Dict[str, Any], endpoints: List[str], mode: str) -> str:
    """
    Set the operating mode of one or more climate control devices.

    Args:
        data: The data dictionary containing devices
        endpoints: List of device endpoint IDs to adjust
        mode: Operating mode to set (heat, cool, auto, off, etc.)

    Returns:
        A JSON string with the result of the operation
    """
    if not endpoints:
        return json.dumps({
            "success": False,
            "message": "No devices specified"
        })

    if mode is None:
        return json.dumps({
            "success": False,
            "message": "No mode specified"
        })

    # Validate the mode is one of the supported modes
    valid_modes = ["heat", "cool", "auto", "fan_only", "dry", "off"]
    if mode not in valid_modes:
        return json.dumps({
            "success": False,
            "message": f"Invalid mode. Must be one of: {', '.join(valid_modes)}"
        })

    # Get the current user's home ID
    home_id = get_user_home_id(data)

    results = []
    for endpoint in endpoints:
        device = find_device_by_endpoint(data, endpoint, home_id)
        if device and "climate_set_mode" in device["supported_apis"]:
            # Update the device state directly in the data dictionary
            for i, d in enumerate(data["devices"]):
                if d["endpoint"] == endpoint and (home_id is None or d["home_id"] == home_id):
                    if "state" not in data["devices"][i]:
                        data["devices"][i]["state"] = {}
                    data["devices"][i]["state"]["mode"] = mode
                    success = True
                    break
            else:
                success = False

            if success:
                results.append({
                    "endpoint": endpoint,
                    "name": device["name"],
                    "success": True,
                    "message": f"Set {device['name']} mode to {mode}",
                    "mode": mode
                })
            else:
                results.append({
                    "endpoint": endpoint,
                    "success": False,
                    "message": f"Failed to update state for device with endpoint {endpoint}"
                })
        else:
            results.append({
                "endpoint": endpoint,
                "success": False,
                "message": f"Device with endpoint {endpoint} not found or does not support mode setting"
            })

    return json.dumps({
        "success": any(result["success"] for result in results),
        "results": results
    })
```

